import Foundation

// MARK: - Source text

/// Helpers for laying out generated Swift so `swift format` leaves it unchanged.
enum SourceText {
    /// The length a line must stay under.
    static let lineLength = 140

    /// The first lines of every generated file.
    static func header(from sources: [CatalogSource]) -> [String] {
        let catalogs = sources.map(\.snapshotPath).joined(separator: ", ")
        return ["// Generated by ModelCatalogGenerator from \(catalogs). Don't edit.", ""]
    }

    /// Text that fits in a doc comment: on one line, with runs of whitespace as single spaces, and without characters
    /// that don't print.
    ///
    /// Catalog text reaches the generated code's comments, so a line break in it could otherwise end a comment and
    /// start code.
    static func docText(_ text: String) -> String {
        let printable = text.unicodeScalars.filter { $0.isPrintable || $0.properties.isWhitespace }
        return String(String.UnicodeScalarView(printable)).split(whereSeparator: \.isWhitespace).joined(separator: " ")
    }

    /// A doc comment for a paragraph, made safe by ``docText(_:)`` and wrapped to the line length.
    static func documentation(_ text: String, indent: String) -> [String] {
        let text = docText(text)
        guard !text.isEmpty else { return ["\(indent)///"] }
        var lines: [String] = []
        var line = ""
        for word in text.split(separator: " ") {
            let longer = line.isEmpty ? String(word) : "\(line) \(word)"
            if !line.isEmpty, "\(indent)/// \(longer)".count >= lineLength {
                lines.append("\(indent)/// \(line)")
                line = String(word)
            } else {
                line = longer
            }
        }
        return lines + ["\(indent)/// \(line)"]
    }

    /// The file's text: its lines joined, with one final newline.
    static func file(_ lines: [String]) -> String {
        lines.joined(separator: "\n") + "\n"
    }
}

// MARK: - Literals

/// Swift source text for literal values.
enum SwiftLiteral {
    /// A string literal, with quotes and backslashes escaped, and every character that doesn't print, such as a line
    /// break, written as an escape.
    static func string(_ value: String) -> String {
        var escaped = ""
        for scalar in value.unicodeScalars {
            switch scalar {
            case "\\": escaped += "\\\\"
            case "\"": escaped += "\\\""
            case "\n": escaped += "\\n"
            case "\r": escaped += "\\r"
            case "\t": escaped += "\\t"
            case _ where !scalar.isPrintable: escaped += "\\u{\(String(scalar.value, radix: 16, uppercase: true))}"
            default: escaped.unicodeScalars.append(scalar)
            }
        }
        return "\"\(escaped)\""
    }

    /// An integer literal with its digits grouped in threes, such as `200_000`.
    static func integer(_ value: Int) -> String {
        let digits = String(value.magnitude)
        var grouped = ""
        for (offset, digit) in digits.enumerated() {
            if offset > 0, (digits.count - offset) % 3 == 0 { grouped += "_" }
            grouped.append(digit)
        }
        return value < 0 ? "-" + grouped : grouped
    }

    /// A `Date` expression for a number of seconds since 1970.
    static func date(secondsSince1970 seconds: Int) -> String {
        "Date(timeIntervalSince1970: \(integer(seconds)))"
    }

    /// A `Date` expression for midnight UTC at the start of a day.
    static func date(_ day: CatalogDay) -> String {
        date(secondsSince1970: Int(day.start.timeIntervalSince1970))
    }
}

// MARK: - Identifiers

/// A Swift name made from catalog text, such as a model's static member or an effort word's member.
///
/// The name is kept without backticks, so a suffix such as `Entry` joins the name itself. Its ``description`` spells
/// it the way code must: in backticks when it starts with a digit or is a keyword.
struct SwiftIdentifier: Hashable, CustomStringConvertible {
    /// The names of `Optional`'s cases, which no static member of a vocabulary or model type can take: where an
    /// optional value is expected, `.none` means `Optional.none` rather than the member, and `.some` reads as
    /// `Optional.some`.
    static let optionalCaseNames: Set<String> = ["none", "some"]

    /// The spellings of providers' names in their hand-written API, by the lowercased word.
    private static let spellings = ["openrouter": "openRouter"]

    /// The member name of the effort word that turns reasoning off.
    private static let offMemberName = "off"

    /// The name without backticks.
    let name: String

    var description: String {
        name.first?.isNumber == true || Self.keywords.contains(name) ? "`\(name)`" : name
    }

    /// The name followed by a suffix, such as `Entry`.
    func appending(_ suffix: String) -> SwiftIdentifier {
        SwiftIdentifier(name: name + suffix)
    }

    /// A lower-camel-case member name for a model id or a vocabulary word.
    ///
    /// ASCII letters and digits form words, and every other character separates them. Words join in camel case, and
    /// adjacent numbers keep an underscore between them, so `anthropic/claude-opus-5.5` becomes
    /// `anthropicClaudeOpus5_5` and a `:free` variant gets a `Free` suffix. Text without ASCII letters or digits gets
    /// an empty name, which ``check(_:reserved:kind:)`` refuses. A provider's own name keeps the spelling its
    /// hand-written API uses, such as `openRouter` in `openRouterAuto`.
    static func member(for text: String) -> SwiftIdentifier {
        var name = ""
        for found in text.split(whereSeparator: { !($0.isASCII && ($0.isLetter || $0.isNumber)) }) {
            let word = spellings[found.lowercased()].map { Substring($0) } ?? found
            if name.isEmpty {
                name = word.prefix(1).lowercased() + word.dropFirst()
            } else if name.last?.isNumber == true, word.first?.isNumber == true {
                name += "_" + word
            } else {
                name += word.capitalizingFirstLetter
            }
        }
        return SwiftIdentifier(name: name)
    }

    /// The member name for an effort word, with `none` spelled `off`.
    static func effortMember(for word: String) -> SwiftIdentifier {
        word == EffortRanking.offWord ? SwiftIdentifier(name: offMemberName) : member(for: word)
    }

    /// The name with its first letter uppercased, which turns a member name into the matching type name, such as
    /// `AnthropicClaudeOpus5_5` for `anthropicClaudeOpus5_5`.
    var capitalized: SwiftIdentifier {
        SwiftIdentifier(name: name.capitalizingFirstLetter)
    }

    /// Checks that every value in a scope gets a name of its own that the scope doesn't already declare.
    ///
    /// - Parameters:
    ///   - named: Each value with its name. A value can appear more than once, with different names.
    ///   - reserved: The names the scope already declares.
    ///   - kind: What the values are, such as `OpenRouter models`, for the error message.
    /// - Throws: ``GeneratorError/invalidCatalog(_:)`` naming the values that get no name, a reserved name or the
    ///   same name as another value.
    static func check(
        _ named: [(identifier: SwiftIdentifier, value: String)],
        reserved: Set<String> = [],
        kind: String
    ) throws(GeneratorError) {
        func list(_ values: [String]) -> String { Set(values).sorted().joined(separator: ", ") }

        let unnamed = named.filter(\.identifier.name.isEmpty).map(\.value)
        guard unnamed.isEmpty else { throw .invalidCatalog("These \(kind) get no Swift name: \(list(unnamed)).") }
        let taken = named.filter { reserved.contains($0.identifier.name) }.map(\.value)
        guard taken.isEmpty else { throw .invalidCatalog("These \(kind) get a Swift name that's taken: \(list(taken)).") }
        let clashes = Dictionary(grouping: named, by: \.identifier).values.map { $0.map(\.value) }.filter { Set($0).count > 1 }
        guard clashes.isEmpty else {
            throw .invalidCatalog("These \(kind) get the same Swift name: \(list(clashes.flatMap(\.self))).")
        }
    }

    private static let keywords: Set<String> = [
        "as", "associatedtype", "break", "case", "catch", "class", "continue", "default", "defer", "deinit", "do",
        "else", "enum", "extension", "fallthrough", "false", "fileprivate", "for", "func", "guard", "if", "import", "in",
        "init", "inout", "internal", "is", "let", "nil", "operator", "private", "protocol", "public", "repeat",
        "rethrows", "return", "self", "static", "struct", "subscript", "super", "switch", "throw", "throws", "true",
        "try", "typealias", "var", "where", "while",
    ]
}

extension StringProtocol {
    fileprivate var capitalizingFirstLetter: String {
        prefix(1).uppercased() + dropFirst()
    }
}

// MARK: - Expressions

/// A Swift expression that lays itself out the way `swift format` keeps it: on one line when that fits, otherwise
/// with one element per line, each laid out the same way.
enum SwiftExpression {
    /// A call's argument.
    struct Argument {
        /// The argument's label, or empty for an unlabeled argument.
        let label: String
        let value: SwiftExpression

        /// The text before the value: the label and a colon, or nothing for an unlabeled argument.
        fileprivate var prefix: String {
            label.isEmpty ? "" : "\(label): "
        }
    }

    /// Text that never breaks, such as a literal.
    case atom(String)
    /// An array literal.
    case array([SwiftExpression])
    /// A call, such as `Self(id: "a")`.
    case call(String, arguments: [Argument])

    /// A call with only the arguments that have a value, so an argument left at its default can be `nil`.
    static func call(_ name: String, _ arguments: KeyValuePairs<String, SwiftExpression?>) -> SwiftExpression {
        .call(name, arguments: arguments.compactMap { label, value in value.map { Argument(label: label, value: $0) } })
    }

    /// The expression on one line.
    private var line: String {
        switch self {
        case .atom(let text): text
        case .array(let elements): "[\(elements.map(\.line).joined(separator: ", "))]"
        case .call(let name, let arguments):
            "\(name)(\(arguments.map { $0.prefix + $0.value.line }.joined(separator: ", ")))"
        }
    }

    /// The expression's lines, after `prefix`, such as a label, and before `suffix`, such as a comma.
    ///
    /// - Parameters:
    ///   - indent: The indentation of the first and last lines; elements get four more spaces.
    ///   - prefix: Text before the expression on its first line.
    ///   - suffix: Text after the expression on its last line.
    ///   - breaks: Whether to break the expression even when it fits on one line.
    /// - Returns: The lines, without line breaks.
    func lines(indent: String, prefix: String = "", suffix: String = "", breaks: Bool = false) -> [String] {
        let oneLine = indent + prefix + line + suffix
        guard breaks || oneLine.count >= SourceText.lineLength else { return [oneLine] }
        let inner = indent + "    "
        switch self {
        case .array(let elements) where !elements.isEmpty:
            // `swift format` puts a comma after every element of a broken array, unless it has only one.
            let comma = elements.count > 1 ? "," : ""
            return [indent + prefix + "["] + elements.flatMap { $0.lines(indent: inner, suffix: comma) } + [indent + "]" + suffix]
        case .call(let name, let arguments) where !arguments.isEmpty:
            let argumentLines = arguments.enumerated().flatMap { index, argument in
                argument.value.lines(indent: inner, prefix: argument.prefix, suffix: index < arguments.count - 1 ? "," : "")
            }
            return [indent + prefix + name + "("] + argumentLines + [indent + ")" + suffix]
        default:
            return [oneLine]
        }
    }
}

// MARK: - Printable scalars

extension Unicode.Scalar {
    /// Whether the scalar shows as itself in source text: not a control, format or separator character, and not
    /// unassigned or private.
    ///
    /// Format characters include the ones that reorder text, so source can't display differently from what it does.
    fileprivate var isPrintable: Bool {
        switch properties.generalCategory {
        case .control, .format, .lineSeparator, .paragraphSeparator, .surrogate, .privateUse, .unassigned: false
        default: true
        }
    }
}
